public Element nextElementSibling() {
    Element parent = parent();
    if (parent == null) {
        return null;
    }
    Elements siblings = parent.children();
    int index = siblings.indexOf(this);
    if (index == -1 || index == siblings.size() - 1) {
        return null;
    }
    return siblings.get(index + 1);
}

